/* ---------- engine auto demo + format-tile language ticker ---------- */
function engModule(){ return PAGES[page].modules.find(m=>m.type==='engine'); }
function kSize(){
  const st=document.getElementById('stage'), ad=document.getElementById('ad'); if(!st||!ad) return;
  const [rw,rh]=KBY.format.opts[KST[page].format].r;
  const W=Math.max(200, st.clientWidth-24), H=window.innerWidth<760 ? 420 : 540;
  let w=W, h=w*rh/rw; if(h>H){ h=H; w=h*rw/rh; }
  ad.style.width=w+'px'; ad.style.height=h+'px'; ad.style.setProperty('--u', (Math.sqrt(w*h)/100).toFixed(2)+'px');
}
function kRender(){
  const ad=document.getElementById('ad'); const st=KST[page]; if(!ad||!st) return;
  const L=KBY.layout.opts[st.layout].c, hook=KBY.hook.opts[st.hook], lang=KBY.lang.opts[st.lang], sc=KBY.scene.opts[st.scene], fm=KBY.format.opts[st.format];
  ad.className='kad l-'+L+(fm.r[0]<fm.r[1]?' portrait':'');
  document.getElementById('adH').textContent=hook.h[st.lang]; document.getElementById('adS').textContent=hook.s[st.lang]; document.getElementById('adC').textContent=lang.cta;
  const fld=ad.querySelector('.field'); fld.setAttribute('lang', lang.c); if(lang.rtl) fld.setAttribute('dir','rtl'); else fld.removeAttribute('dir');
  ad.setAttribute('aria-label','KITE ad: '+hook.h[st.lang]);
  ad.querySelectorAll('video').forEach(v=>{ const on=v.dataset.scene===sc.c; v.classList.toggle('on',on); if(on && !REDUCED){ const p=v.play(); if(p&&p.catch)p.catch(()=>{}); } });
  const c=document.getElementById('code'); if(c) c.textContent=`layout=${L} · hook=${hook.c} · scene=${sc.c} · lang=${lang.c} · ratio=${fm.c}`;
  document.querySelectorAll('[data-keng]').forEach(b=>b.setAttribute('aria-pressed', String(st[b.dataset.keng]===Number(b.dataset.v))));
  kSize();
}
window.addEventListener('resize', kSize);
function setEng(key, v){ const st=KST[page]; if(!st) return; st[key]=Number(v); kRender(); }
function autoStep(){
  const m = engModule(); if(!m || !AUTO.on || !AUTO.vis || editing || document.hidden || !KST[page]) return;
  const vis = m.order.filter(k=>{ const b=document.querySelector(`[data-keng="${k}"]`); return b && b.offsetParent!==null; });
  const pool = vis.length ? vis : m.order; const k = pool[Math.floor(Math.random()*pool.length)]; const n = KBY[k].opts.length;
  let v; do{ v=Math.floor(Math.random()*n); }while(v===KST[page][k] && n>1);
  setEng(k, v);
}
function setAuto(on){ AUTO.on = on; const b=document.getElementById('autoSw'); if(b) b.setAttribute('aria-checked', String(on)); }
function watchEngine(){
  if(AUTO.obs) AUTO.obs.disconnect(); AUTO.vis = false;
  const st = document.getElementById('stage'); if(!st || !('IntersectionObserver' in window)) return;
  AUTO.obs = new IntersectionObserver(es=>{ AUTO.vis = es.some(x=>x.isIntersecting); }, {threshold:0.35});
  AUTO.obs.observe(st);
}
AUTO.t = setInterval(autoStep, 2400);
const VF_LANG = ['EN','DE','TR','ES','FR']; let vfi = 0;
if(!REDUCED) setInterval(()=>{ vfi=(vfi+1)%VF_LANG.length; document.querySelectorAll('.vf-lang').forEach(el=>el.textContent=VF_LANG[vfi]); }, 1200);

/* ---------- reel pop-up ---------- */
const lb = document.createElement('div'); lb.className='lb'; lb.id='lb'; lb.hidden=true; lb.setAttribute('role','dialog'); lb.setAttribute('aria-modal','true'); lb.setAttribute('aria-label','Toggle reel');
lb.innerHTML = '<button type="button" class="lb-x" aria-label="Close">×</button><video controls playsinline preload="none"></video>';
document.body.appendChild(lb);
const lbv = lb.querySelector('video'); let lbBack = null;
function openReel(){
  lbBack = document.activeElement; lbv.src = mediaSrc('reelFull') || mediaSrc('reel'); lbv.poster = mediaSrc('reelPoster') || '';
  lb.hidden = false; document.body.style.overflow='hidden'; lb.querySelector('.lb-x').focus();
  const pr = lbv.play(); if(pr && pr.catch) pr.catch(()=>{});
}
function closeReel(){ lbv.pause(); lb.hidden = true; document.body.style.overflow=''; if(lbBack && lbBack.focus) lbBack.focus(); }
lb.addEventListener('click', e=>{ if(e.target===lb || e.target.closest('.lb-x')) closeReel(); });
document.addEventListener('keydown', e=>{ if(e.key==='Escape' && !lb.hidden) closeReel(); });
/* pause tile videos off-screen */
const vidObs = 'IntersectionObserver' in window ? new IntersectionObserver(es=>es.forEach(x=>{ const v=x.target; if(x.isIntersecting && !REDUCED){ const p=v.play(); if(p&&p.catch) p.catch(()=>{}); } else v.pause(); }), {threshold:0.1}) : null;
function watchVideos(){ if(!vidObs) return; vidObs.disconnect(); document.querySelectorAll('.reelvid').forEach(v=>vidObs.observe(v)); }

let formObs = null;
function watchForm(){
  if(!('IntersectionObserver' in window)) return;
  if(formObs) formObs.disconnect();
  const f = document.getElementById('mod-form'); if(!f) return;
  formObs = new IntersectionObserver(es=>{ document.body.classList.toggle('form-in-view', es.some(x=>x.isIntersecting)); }, {threshold:0.15});
  formObs.observe(f);
}
function applyEditable(){
  document.querySelectorAll('#page [data-k]').forEach(el=>{
    if(editing){ el.setAttribute('contenteditable','plaintext-only'); if(el.contentEditable!=='plaintext-only') el.setAttribute('contenteditable','true'); el.setAttribute('spellcheck','false'); }
    else el.removeAttribute('contenteditable');
  });
}
function refreshTexts(){
  document.querySelectorAll('[data-k]').forEach(el=>{
    if(el === document.activeElement) return;
    const v = val(el.dataset.k); if(v!==undefined && el.textContent!==v) el.textContent = v;
  });
}
function syncPlan(){
  const sel = planSel();
  document.querySelectorAll('[data-plan]').forEach(t=>{ const on = Number(t.dataset.plan)===sel; t.classList.toggle('t-sky',on); t.classList.toggle('t-grey',!on); t.setAttribute('aria-pressed', String(on)); });
  document.querySelectorAll('[data-planchip]').forEach(b=>b.setAttribute('aria-pressed', String(Number(b.dataset.planchip)===sel)));
  const r = document.getElementById('calcRes'); if(r){ r.innerHTML = calcOut(); applyEditable(); }
}

