const toastEl = document.getElementById('toast'); let tt;
function toast(msg){ if(!toastEl) return; toastEl.textContent = msg; toastEl.classList.add('on'); clearTimeout(tt); tt = setTimeout(()=>toastEl.classList.remove('on'), 1800); }
function saveText(){} function saveLayout(){} function updLayout(){}
page = PAGES[document.body.dataset.page] ? document.body.dataset.page : 'main';
