/* ---------- events ---------- */
function setPage(p){ if(!PAGES[p]) p='main'; page=p; render(); window.scrollTo({top:0}); }
function goTo(target){
  if(!target) return;
  if(target.startsWith('/')){ location.href = target; return; }
  const t = document.getElementById('mod-'+target); if(t) t.scrollIntoView({behavior:'smooth', block:'start'});
}
document.getElementById('mcta').addEventListener('click', ()=>goTo('form'));
const page$ = document.getElementById('page');
page$.addEventListener('click', e=>{
  const mu = e.target.closest('[data-mup]');
  if(mu){ e.preventDefault(); mfile.accept = MEDIA_ACC[mu.dataset.mup]; mfile.dataset.slot = mu.dataset.mup; mfile.click(); return; }
  const mr = e.target.closest('[data-mreset]');
  if(mr){ e.preventDefault(); saveMedia(mr.dataset.mreset, null); return; }
  if(!editing && e.target.closest('[data-reel]')){ openReel(); return; }
  const sw = e.target.closest('#autoSw');
  if(sw){ setAuto(!AUTO.on); if(AUTO.on) autoStep(); return; }
  const fx = e.target.closest('[data-fx]');
  if(fx){ updLayout(l=>{ const id=fx.dataset.fx; l.fx={...l.fx,[id]: !fxOn(l,id)}; }); return; }
  const keng = e.target.closest('[data-keng]');
  if(keng){ if(e.isTrusted) setAuto(false); setEng(keng.dataset.keng, keng.dataset.v); return; }
  const eng = e.target.closest('[data-eng]');
  if(eng){ if(e.isTrusted) setAuto(false); const st=ENG[page]; const key=eng.dataset.eng; st[key] = key==='hook'?Number(eng.dataset.v):eng.dataset.v;
    eng.parentElement.querySelectorAll('.pill').forEach(b=>b.setAttribute('aria-pressed', String(b===eng)));
    document.getElementById('stage').innerHTML = adHTML(st);
    document.getElementById('code').textContent = codeLine(PAGES[page].modules.find(m=>m.type==='engine'||m.type==='heroengine'), st);
    return; }
  const cb = e.target.closest('[data-calc]');
  if(cb){ calcState()[cb.dataset.calc] = Number(cb.dataset.v); cb.parentElement.querySelectorAll('.pill').forEach(b=>b.setAttribute('aria-pressed', String(b===cb))); syncPlan(); return; }
  const pc = e.target.closest('[data-planchip]');
  if(pc){ PLANSEL[page] = Number(pc.dataset.planchip); syncPlan(); return; }
  const ch = e.target.closest('[data-chip]');
  if(ch){ FORM[page].chip = Number(ch.dataset.chip); ch.parentElement.querySelectorAll('.pill').forEach(b=>b.setAttribute('aria-pressed', String(b===ch))); return; }
  if(editing && e.target.closest('[data-k]')){ e.preventDefault(); return; }
  const qa = e.target.closest('.qa');
  if(qa && !editing){ qa.classList.toggle('open'); return; }
  const pt = e.target.closest('[data-plan]');
  if(pt){ PLANSEL[page] = Number(pt.dataset.plan); syncPlan(); return; }
  const go = e.target.closest('[data-go]');
  if(go){ goTo(go.dataset.go); return; }
  if(e.target.closest('[data-focus]')){ const i=document.getElementById('f1-'+page); if(i) i.focus(); return; }
  const mv = e.target.closest('[data-mv]');
  if(mv){ updLayout(l=>{ const i=l.order.indexOf(mv.dataset.id), j=i+Number(mv.dataset.mv); if(j<0||j>=l.order.length) return; [l.order[i],l.order[j]]=[l.order[j],l.order[i]]; }); return; }
  const hd = e.target.closest('[data-hide]');
  if(hd){ updLayout(l=>{ const id=hd.dataset.hide; l.hidden = l.hidden.includes(id)?l.hidden.filter(x=>x!==id):[...l.hidden,id]; }); return; }
  const w = e.target.closest('[data-w]');
  if(w){ updLayout(l=>{ const id=w.dataset.w; const m=PAGES[page].modules.find(x=>x.id===id); const cur=l.span[id]||m.span||12; l.span={...l.span,[id]:WIDTHS[(WIDTHS.indexOf(cur)+1)%WIDTHS.length]}; }); return; }
  const t = e.target.closest('[data-t]');
  if(t){ updLayout(l=>{ const id=t.dataset.t; const m=PAGES[page].modules.find(x=>x.id===id); const cur=l.tone[id]||m.tone||'grey'; l.tone={...l.tone,[id]:TONES[(TONES.indexOf(cur)+1)%TONES.length]}; }); return; }
  const rs = e.target.closest('[data-reset]');
  if(rs){
    if(rs.dataset.armed!=='1'){ rs.dataset.armed='1'; rs.textContent='Точно сбросить?'; setTimeout(()=>{ if(rs.isConnected){ rs.dataset.armed=''; rs.textContent='Сбросить тексты'; } }, 3000); return; }
    const pre = `${page}.${rs.dataset.id}.`; const keys = Object.keys(TX).filter(k=>k.startsWith(pre) && !k.endsWith('.note'));
    (async()=>{ for(const k of keys) await saveText(k, DEF[k]); render(); toast('Тексты модуля сброшены'); })();
  }
});
page$.addEventListener('keydown', e=>{
  if(e.target.matches && e.target.matches('[data-k]') && e.key==='Enter' && !e.shiftKey){ e.preventDefault(); e.target.blur(); return; }
  if(e.target.matches && e.target.matches('[data-go][role="link"]') && e.key==='Enter' && !editing){ e.preventDefault(); goTo(e.target.dataset.go); return; }
  if(e.target.matches && e.target.matches('.qa .q') && (e.key==='Enter'||e.key===' ') && !editing){ e.preventDefault(); e.target.closest('.qa').classList.toggle('open'); return; }
  if(e.target.matches && e.target.matches('[data-plan]') && (e.key==='Enter'||e.key===' ')){ e.preventDefault(); PLANSEL[page] = Number(e.target.dataset.plan); syncPlan(); }
});
page$.addEventListener('paste', e=>{ if(!e.target.closest || !e.target.closest('[data-k]')) return; e.preventDefault(); const t=(e.clipboardData||window.clipboardData).getData('text/plain'); document.execCommand('insertText', false, t.replace(/\s+/g,' ')); });
page$.addEventListener('focusout', e=>{
  const el = e.target.closest && e.target.closest('[data-k]'); if(!el || !editing) return;
  const k = el.dataset.k; const v = el.textContent.replace(/\s+/g,' ').trim();
  if(!v){ el.textContent = val(k); return; }
  if(v !== val(k)) saveText(k, v);
});
/* ---------- lead form → Formspree ---------- */
const FORM_ENDPOINT = 'https://formspree.io/f/mrppzdrv';
const LANDING_NAME = {main:'Main', agencies:'Agencies', brands:'Brands'};
page$.addEventListener('submit', async e=>{ e.preventDefault(); if(editing) return;
  const f = e.target; if(f.id!=='leadForm' || f.dataset.sending) return;
  const g = id => { const el=document.getElementById(id+'-'+page); return el ? el.value.trim() : ''; };
  const em=document.getElementById('f2-'+page), err=document.getElementById('formErr'), d=document.getElementById('formDone'), btn=f.querySelector('.submit');
  const ok = em && /^\S+@\S+\.\S+$/.test(em.value.trim());
  if(d) d.hidden = true;
  if(!ok){ err.textContent='Please add a valid work e-mail.'; err.hidden=false; if(em){ em.setAttribute('aria-invalid','true'); em.focus(); } return; }
  em.removeAttribute('aria-invalid'); err.hidden = true;
  const hp = f.querySelector('[name="_gotcha"]');
  const m = PAGES[page].modules.find(x=>x.type==='form'); const K = k=>`${page}.form.${k}`;
  const chip = FORM[page] ? FORM[page].chip : null;
  const data = { _subject:`New request — Toggle Concepts (${LANDING_NAME[page]})`, landing:LANDING_NAME[page], name:g('f1'), email:em.value.trim(), company:g('f3') };
  if(m.plan){ const i=planSel(); data.plan = `${planName(i)} · ${CONCEPTS[i]} concepts · ${planPrice(i)}/mo`; }
  data[val(K('f4'))] = chip!=null ? m.chips[chip] : '';
  data[val(K('f5'))] = g('f5');
  if(hp && hp.value){ d.hidden=false; f.reset(); return; }
  f.dataset.sending='1'; btn.disabled=true; btn.style.opacity='.6';
  try{
    const r = await fetch(FORM_ENDPOINT, {method:'POST', headers:{'Accept':'application/json','Content-Type':'application/json'}, body:JSON.stringify(data)});
    if(!r.ok) throw new Error('status '+r.status);
    d.hidden=false; f.reset(); if(FORM[page]) FORM[page].chip=null;
    f.querySelectorAll('[data-chip]').forEach(b=>b.setAttribute('aria-pressed','false'));
  }catch(_){ err.textContent='Couldn’t send your request. Please try again in a moment.'; err.hidden=false; }
  finally{ delete f.dataset.sending; btn.disabled=false; btn.style.opacity=''; }
});
